});

describe("Cart - checkout", () => {
  it("checkout without collaborators returns sync totals and lines", async () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.lines).toHaveLength(1);
    expect(result.lines[0]!.product.id).toBe("a");
  });

  it("refreshes prices via priceFetcher before computing totals", async () => {
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };
    const cart = new Cart();
    cart.add(productA, 2); // original price 1000

    const result = await cart.checkout({ priceFetcher });
    // refreshed price: 1500 * 2 = 3000
    expect(result.totals.subtotalCents).toBe(3000);
    expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
  });

  it("throws InventoryError when item is unavailable", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: false, reason: "out of stock" }),
    };
    const cart = new Cart();
    cart.add(productA, 1);

    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(1);
    }
  });

  it("throws InventoryError for partial-stock denial (availableQuantity < requested)", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 1,
      }),
    };
    const cart = new Cart();
    cart.add(productA, 5);

    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(5);
      expect(invErr.available).toBe(1);
    }
  });

  it("succeeds when inventory is available", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const cart = new Cart();
    cart.add(productA, 2);

    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("succeeds when availableQuantity >= requested", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 10,
      }),
    };
    const cart = new Cart();
    cart.add(productA, 5);
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(5000);
  });

  it("uses asyncTaxProvider for tax calculation during checkout", async () => {
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.10),
    };
    const cart = new Cart({ region: "US" });
    cart.add(productA, 10); // subtotal = 10000

    const result = await cart.checkout({ asyncTaxProvider });
    // Tax = floor(10000 * 0.10) = 1000
    expect(result.totals.taxCents).toBe(1000);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
  });

  it("combines priceFetcher + discount + asyncTaxProvider + shipping", async () => {
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(2000),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.05),
    };
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(1000),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({
      discountPolicy: discount,
      shippingCalculator: shipping,
      region: "FR",
    });
    cart.add(productA, 5);

    const result = await cart.checkout({ priceFetcher, asyncTaxProvider });
    // Refreshed subtotal: 2000 * 5 = 10000
    expect(result.totals.subtotalCents).toBe(10000);
    // Discount: 1000 (clamped from computeDiscountCents)
    expect(result.totals.discountCents).toBe(1000);
    // Discounted subtotal: 9000
    // Tax: floor(9000 * 0.05) = 450
    expect(result.totals.taxCents).toBe(450);
    // Shipping: 500
    expect(result.totals.shippingCents).toBe(500);
    // Total: 9000 + 450 + 500 = 9950
    expect(result.totals.totalCents).toBe(9950);
  });

  it("propagates priceFetcher rejection", async () => {
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
    };
    const cart = new Cart();
    cart.add(productA, 1);
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
      "price service down",
    );
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    const cart = new Cart();
    cart.add(productA, 1);
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
      "tax service down",
    );
  });

  it("checks inventory for each line in order, first denial wins", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi.fn()
        .mockResolvedValueOnce({ available: true })
        .mockResolvedValueOnce({ available: false, reason: "discontinued" }),
    };
    const cart = new Cart();
    cart.add(productA, 1);
    cart.add(productB, 1);

    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      expect((err as InventoryError).productId).toBe("b");
    }
    expect(inventoryChecker.check).toHaveBeenCalledTimes(2);
  });

  it("checkout with empty cart returns zero totals", async () => {
    const cart = new Cart();
    const result = await cart.checkout();
    expect(result.totals.totalCents).toBe(0);
    expect(result.lines).toHaveLength(0);
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([0, 100, 999_99, -50])(
    "returns 0 regardless of subtotal (%i)",
    (subtotal) => {
      expect(policy.computeDiscountCents(subtotal)).toBe(0);
    },
  );
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, 101, NaN, Infinity, -Infinity])(
      "rejects out-of-range percent %s",
      (pct) => {
        expect(() => new PercentageDiscountPolicy(pct)).toThrow(RangeError);
      },
    );

    it.each([0, 50, 100])("accepts valid percent %i", (pct) => {
      expect(() => new PercentageDiscountPolicy(pct)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("computes 10% of 10000 = 1000", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(10000)).toBe(1000);
    });

    it("rounds down fractional cents (15% of 999 = 149.85 → 149)", () => {
      const policy = new PercentageDiscountPolicy(15);
      expect(policy.computeDiscountCents(999)).toBe(149);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("100% discount equals the subtotal", () => {
      const policy = new PercentageDiscountPolicy(100);
      expect(policy.computeDiscountCents(5000)).toBe(5000);
    });

    it("0% discount returns 0", () => {
      const policy = new PercentageDiscountPolicy(0);
      expect(policy.computeDiscountCents(5000)).toBe(0);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects negative amount", () => {
      expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
    });

    it("rejects non-integer amount", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts zero", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns the fixed amount when subtotal exceeds it", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(1000)).toBe(500);
    });

    it("caps at subtotal when discount exceeds subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(2000);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("discount equals subtotal exactly", () => {
      const policy = new FixedAmountDiscountPolicy(1000);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums independent discount results against original subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10); // 1000
      const p2 = new FixedAmountDiscountPolicy(500); // 500
      const composite = new CompositeDiscountPolicy([p1, p2], "sum");
      // Both receive subtotal=10000; 10% of 10000 = 1000, plus 500 = 1500
      expect(composite.computeDiscountCents(10000)).toBe(1500);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("defaults to sum mode when mode is omitted", () => {
      const p1 = new FixedAmountDiscountPolicy(200);
      const p2 = new FixedAmountDiscountPolicy(300);
      const composite = new CompositeDiscountPolicy([p1, p2]);
      expect(composite.computeDiscountCents(1000)).toBe(500);
    });

    it("can exceed subtotal (caller clamps)", () => {
      const p1 = new FixedAmountDiscountPolicy(800);
      const p2 = new FixedAmountDiscountPolicy(800);
      const composite = new CompositeDiscountPolicy([p1, p2], "sum");
      // Each returns min(800, 1000) = 800; sum = 1600 > 1000
      expect(composite.computeDiscountCents(1000)).toBe(1600);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10); // 10% of 10000 = 1000
      const p2 = new PercentageDiscountPolicy(10); // 10% of 9000 = 900
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      expect(composite.computeDiscountCents(10000)).toBe(1900);
    });

    it("order matters in chain mode", () => {
      const fixed = new FixedAmountDiscountPolicy(500);
      const pct = new PercentageDiscountPolicy(10);

      const fixedFirst = new CompositeDiscountPolicy(
        [fixed, pct],
        "chain",
      );
      const pctFirst = new CompositeDiscountPolicy(
        [pct, fixed],
        "chain",
      );

      // fixed first: 500 off 10000 → remaining 9500, then 10% of 9500 = 950, total = 1450
      expect(fixedFirst.computeDiscountCents(10000)).toBe(1450);
      // pct first: 10% of 10000 = 1000, remaining 9000, then min(500, 9000) = 500, total = 1500
      expect(pctFirst.computeDiscountCents(10000)).toBe(1500);
    });

    it("chain cannot exceed subtotal", () => {
      const p1 = new FixedAmountDiscountPolicy(800);
      const p2 = new FixedAmountDiscountPolicy(800);
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      // p1: min(800, 1000) = 800, remaining = 200; p2: min(800, 200) = 200; total = 1000
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});

