            { upToGrams: 1.5, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 500, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const brackets = [
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
      { upToGrams: 5000, costCents: 1200 },
    ];

    it("returns 0 for empty cart", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([], 0)).toBe(0);
    });

    it("returns 0 when total weight is 0 (no weightGrams)", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(
        calc.computeShippingCents([makeLine("a", undefined, 2)], 1000),
      ).toBe(0);
    });

    it("selects the first bracket (weight within lowest bracket)", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 200g * 2 = 400g <= 500g bracket
      expect(
        calc.computeShippingCents([makeLine("a", 200, 2)], 1000),
      ).toBe(300);
    });

    it("selects bracket at exact boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 500g exactly → first bracket
      expect(
        calc.computeShippingCents([makeLine("a", 500, 1)], 1000),
      ).toBe(300);
    });

    it("selects the next bracket when weight exceeds boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 501g → second bracket (up to 1000g)
      expect(
        calc.computeShippingCents([makeLine("a", 501, 1)], 1000),
      ).toBe(600);
    });

    it("selects middle bracket", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 1000g exactly → second bracket
      expect(
        calc.computeShippingCents([makeLine("a", 1000, 1)], 1000),
      ).toBe(600);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      const calc = new WeightBasedShippingCalculator(brackets, 2000);
      // 6000g > 5000g → overflow
      expect(
        calc.computeShippingCents([makeLine("a", 6000, 1)], 1000),
      ).toBe(2000);
    });

    it("falls back to heaviest bracket cost when no overflow configured", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 6000g > 5000g → last bracket cost (1200)
      expect(
        calc.computeShippingCents([makeLine("a", 6000, 1)], 1000),
      ).toBe(1200);
    });

    it("sorts brackets internally regardless of input order", () => {
      const unsorted = [
        { upToGrams: 5000, costCents: 1200 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 600 },
      ];
      const calc = new WeightBasedShippingCalculator(unsorted);
      // 400g → should still match the 500g bracket
      expect(
        calc.computeShippingCents([makeLine("a", 400, 1)], 1000),
      ).toBe(300);
    });

    it("sums weights across multiple lines", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 300, 1), makeLine("b", 250, 1)];
      // 300 + 250 = 550g → second bracket (up to 1000g)
      expect(calc.computeShippingCents(lines, 1000)).toBe(600);
    });
  });
});

