import { describe, it, expect, vi, beforeEach } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import {
  InventoryError,
  type InventoryChecker,
  type PriceFetcher,
} from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2000, weightGrams: 500 };

describe("Cart - line management", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart();
  });

  it("add increases itemCount", () => {
    cart.add(productA, 2);
    expect(cart.itemCount).toBe(2);
  });

  it("add merges quantities for same product", () => {
    cart.add(productA, 2);
    cart.add(productA, 3);
    expect(cart.itemCount).toBe(5);
  });

  it("add rejects non-positive quantity", () => {
    expect(() => cart.add(productA, 0)).toThrow(RangeError);
    expect(() => cart.add(productA, -1)).toThrow(RangeError);
  });

  it("add rejects non-integer quantity", () => {
    expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
  });

  it("add rejects negative unitPriceCents", () => {
    const bad: Product = { id: "x", name: "Bad", unitPriceCents: -1 };
    expect(() => cart.add(bad, 1)).toThrow(RangeError);
  });

  it("remove returns true for existing product", () => {
    cart.add(productA, 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove returns false for unknown product", () => {
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity changes line quantity", () => {
    cart.add(productA, 2);
    cart.updateQuantity("a", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity with 0 removes the line", () => {
    cart.add(productA, 2);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity throws for unknown product", () => {
    expect(() => cart.updateQuantity("unknown", 1)).toThrow(
      "not in the cart",
    );
  });

  it("updateQuantity rejects negative quantity", () => {
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("updateQuantity rejects non-integer quantity", () => {
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", 1.5)).toThrow(RangeError);
  });

  it("clear empties the cart", () => {
    cart.add(productA, 1);
    cart.add(productB, 2);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns a deep copy", () => {
    cart.add(productA, 1);
    const snap = cart.snapshot();
    snap[0]!.quantity = 999;
    expect(cart.itemCount).toBe(1);
  });
});

describe("Cart - pricing pipeline", () => {
  it("empty cart has all-zero totals", () => {
    const cart = new Cart();
    const t = cart.totals();
    expect(t.subtotalCents).toBe(0);
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(0);
  });

  it("computes subtotal from lines", () => {
    const cart = new Cart();
    cart.add(productA, 3); // 3 * 1000 = 3000
    cart.add(productB, 2); // 2 * 2000 = 4000
    expect(cart.totals().subtotalCents).toBe(7000);
  });

  it("applies discount, then tax on discounted subtotal, then shipping", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(1000),
    };
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(450),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({
      discountPolicy: discount,
      taxCalculator: tax,
      shippingCalculator: shipping,
      region: "US-CA",
    });
    cart.add(productA, 5); // subtotal = 5000

    const t = cart.totals();
    expect(t.subtotalCents).toBe(5000);
    expect(t.discountCents).toBe(1000);

    // Tax receives discounted subtotal and region
    expect(tax.computeTaxCents).toHaveBeenCalledWith(4000, "US-CA");
    expect(t.taxCents).toBe(450);

    // Shipping receives lines and discounted subtotal
    expect(shipping.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      4000,
    );
    expect(t.shippingCents).toBe(500);

    // total = discountedSubtotal + tax + shipping = 4000 + 450 + 500
    expect(t.totalCents).toBe(4950);
  });

  it("clamps discount to [0, subtotal]", () => {
    const overDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(99999),
    };
    const cart = new Cart({ discountPolicy: overDiscount });
    cart.add(productA, 1); // subtotal = 1000
    const t = cart.totals();
    expect(t.discountCents).toBe(1000);
    expect(t.totalCents).toBe(0);
  });

  it("clamps negative discount to 0", () => {
    const negDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-500),
    };
    const cart = new Cart({ discountPolicy: negDiscount });
    cart.add(productA, 1); // subtotal = 1000
    expect(cart.totals().discountCents).toBe(0);
  });

  it("clamps negative tax to 0", () => {
    const negTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ taxCalculator: negTax });
    cart.add(productA, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const negShip: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ shippingCalculator: negShip });
    cart.add(productA, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("defaults to NoDiscount, NoTax, FreeShipping, region US", () => {
    const cart = new Cart();
    cart.add(productA, 2); // subtotal = 2000
    const t = cart.totals();
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(2000);
  });
});

describe("Cart - checkout", () => {
  it("checkout without collaborators returns sync totals and lines", async () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.lines).toHaveLength(1);
    expect(result.lines[0]!.product.id).toBe("a");
  });

