      check: vi.fn().mockResolvedValue({ available: false, reason: "out of stock" }),
    };
    const cart = new Cart();
    cart.add(productA, 1);

    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(1);
    }
  });

  it("throws InventoryError for partial-stock denial (availableQuantity < requested)", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 1,
      }),
    };
    const cart = new Cart();
    cart.add(productA, 5);

    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(5);
      expect(invErr.available).toBe(1);
    }
  });

  it("succeeds when inventory is available", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const cart = new Cart();
    cart.add(productA, 2);

    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("succeeds when availableQuantity >= requested", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 10,
      }),
    };
    const cart = new Cart();
    cart.add(productA, 5);
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(5000);
  });

  it("uses asyncTaxProvider for tax calculation during checkout", async () => {
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.10),
    };
    const cart = new Cart({ region: "US" });
    cart.add(productA, 10); // subtotal = 10000

    const result = await cart.checkout({ asyncTaxProvider });
    // Tax = floor(10000 * 0.10) = 1000
    expect(result.totals.taxCents).toBe(1000);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
  });

  it("combines priceFetcher + discount + asyncTaxProvider + shipping", async () => {
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(2000),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.05),
    };
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(1000),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({
      discountPolicy: discount,
      shippingCalculator: shipping,
      region: "FR",
    });
    cart.add(productA, 5);

    const result = await cart.checkout({ priceFetcher, asyncTaxProvider });
    // Refreshed subtotal: 2000 * 5 = 10000
    expect(result.totals.subtotalCents).toBe(10000);
    // Discount: 1000 (clamped from computeDiscountCents)
    expect(result.totals.discountCents).toBe(1000);
    // Discounted subtotal: 9000
    // Tax: floor(9000 * 0.05) = 450
    expect(result.totals.taxCents).toBe(450);
    // Shipping: 500
    expect(result.totals.shippingCents).toBe(500);
    // Total: 9000 + 450 + 500 = 9950
    expect(result.totals.totalCents).toBe(9950);
  });

  it("propagates priceFetcher rejection", async () => {
