describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums independent discount results against original subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10); // 1000
      const p2 = new FixedAmountDiscountPolicy(500); // 500
      const composite = new CompositeDiscountPolicy([p1, p2], "sum");
      // Both receive subtotal=10000; 10% of 10000 = 1000, plus 500 = 1500
      expect(composite.computeDiscountCents(10000)).toBe(1500);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("defaults to sum mode when mode is omitted", () => {
      const p1 = new FixedAmountDiscountPolicy(200);
      const p2 = new FixedAmountDiscountPolicy(300);
      const composite = new CompositeDiscountPolicy([p1, p2]);
      expect(composite.computeDiscountCents(1000)).toBe(500);
    });

    it("can exceed subtotal (caller clamps)", () => {
      const p1 = new FixedAmountDiscountPolicy(800);
      const p2 = new FixedAmountDiscountPolicy(800);
      const composite = new CompositeDiscountPolicy([p1, p2], "sum");
      // Each returns min(800, 1000) = 800; sum = 1600 > 1000
      expect(composite.computeDiscountCents(1000)).toBe(1600);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10); // 10% of 10000 = 1000
      const p2 = new PercentageDiscountPolicy(10); // 10% of 9000 = 900
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      expect(composite.computeDiscountCents(10000)).toBe(1900);
    });

    it("order matters in chain mode", () => {
      const fixed = new FixedAmountDiscountPolicy(500);
      const pct = new PercentageDiscountPolicy(10);

      const fixedFirst = new CompositeDiscountPolicy(
        [fixed, pct],
        "chain",
      );
      const pctFirst = new CompositeDiscountPolicy(
        [pct, fixed],
        "chain",
      );

      // fixed first: 500 off 10000 → remaining 9500, then 10% of 9500 = 950, total = 1450
      expect(fixedFirst.computeDiscountCents(10000)).toBe(1450);
      // pct first: 10% of 10000 = 1000, remaining 9000, then min(500, 9000) = 500, total = 1500
      expect(pctFirst.computeDiscountCents(10000)).toBe(1500);
    });

    it("chain cannot exceed subtotal", () => {
      const p1 = new FixedAmountDiscountPolicy(800);
      const p2 = new FixedAmountDiscountPolicy(800);
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      // p1: min(800, 1000) = 800, remaining = 200; p2: min(800, 200) = 200; total = 1000
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});
