+      const calc = new FlatShippingCalculator(599, 5000);
+      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 6000)).toBe(0);
+    });
+
+    it("returns flat fee when subtotal is just below threshold", () => {
+      const calc = new FlatShippingCalculator(599, 5000);
+      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 4999)).toBe(
