import { describe, it, expect, vi } from "vitest";
import {
  InventoryError,
  refreshPrices,
  type PriceFetcher,
} from "../src/inventory.ts";
import type { CartLine } from "../src/product.ts";

const makeLine = (id: string, price: number, qty: number): CartLine => ({
  product: { id, name: id, unitPriceCents: price },
  quantity: qty,
});

describe("InventoryError", () => {
  it("exposes productId, requested, and available fields", () => {
    const err = new InventoryError("out of stock", "abc", 5, 2);
    expect(err.message).toBe("out of stock");
    expect(err.productId).toBe("abc");
    expect(err.requested).toBe(5);
    expect(err.available).toBe(2);
    expect(err.name).toBe("InventoryError");
    expect(err).toBeInstanceOf(Error);
  });

  it("allows undefined available", () => {
    const err = new InventoryError("gone", "xyz", 1, undefined);
    expect(err.available).toBeUndefined();
  });
});

describe("refreshPrices", () => {
  it("updates unitPriceCents from fetcher for each line", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn()
        .mockResolvedValueOnce(1500)
        .mockResolvedValueOnce(2500),
    };
    const lines = [makeLine("a", 1000, 2), makeLine("b", 2000, 1)];
    const refreshed = await refreshPrices(lines, fetcher);

    expect(refreshed).toHaveLength(2);
    expect(refreshed[0]!.product.unitPriceCents).toBe(1500);
    expect(refreshed[0]!.quantity).toBe(2);
    expect(refreshed[1]!.product.unitPriceCents).toBe(2500);
    expect(fetcher.fetchPriceCents).toHaveBeenCalledTimes(2);
    expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("a");
    expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("b");
  });

  it("returns empty array for empty lines", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn(),
    };
    const result = await refreshPrices([], fetcher);
    expect(result).toEqual([]);
    expect(fetcher.fetchPriceCents).not.toHaveBeenCalled();
  });

  it("throws RangeError when fetcher returns negative price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(-100),
    };
    await expect(refreshPrices([makeLine("a", 1000, 1)], fetcher)).rejects.toThrow(
      RangeError,
    );
  });

  it("throws RangeError when fetcher returns non-integer price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(9.99),
    };
    await expect(refreshPrices([makeLine("a", 1000, 1)], fetcher)).rejects.toThrow(
      RangeError,
    );
  });

  it("propagates fetcher rejection", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("fetch failed")),
    };
    await expect(refreshPrices([makeLine("a", 1000, 1)], fetcher)).rejects.toThrow(
      "fetch failed",
    );
  });

  it("does not mutate original lines", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(9999),
    };
    const original = [makeLine("a", 1000, 1)];
    await refreshPrices(original, fetcher);
    expect(original[0]!.product.unitPriceCents).toBe(1000);
  });
});

